INSERT OR IGNORE INTO "Gig" (`id`, `organizerId`, `title`, `description`, `gigType`, `genres`, `eventDate`, `durationHours`, `location`, `venueName`, `budgetCents`, `requirements`, `status`, `createdAt`, `updatedAt`) VALUES ('cmvkitybi000ecsmo29fmu7q2', 'cmvkity8i0001csmo8qpqqbfk', 'Worship band for Sunday morning services', 'We''re a contemporary congregation looking for a keys-led trio to lead two back-to-back Sunday services (9am & 11am). Set list is provided a week ahead; one rehearsal on Saturday afternoon preferred. Sound tech and PA provided.', 'CHURCH_SERVICE', '["Worship","Gospel"]', 1793596816636, 4.0, 'Austin, TX', 'Grace Community Church', 80000, 'Comfortable leading congregational worship. Background check required for all working with youth.', 'OPEN', 1792732816638, 1792732816638);
INSERT OR IGNORE INTO "Gig" (`id`, `organizerId`, `title`, `description`, `gigType`, `genres`, `eventDate`, `durationHours`, `location`, `venueName`, `budgetCents`, `requirements`, `status`, `createdAt`, `updatedAt`) VALUES ('cmvkitybx000gcsmo84ueeq57', 'cmvkity8i0001csmo8qpqqbfk', 'Youth night acoustic set', 'Acoustic duo/set for our high-school youth night (approx. 60 students). Upbeat, family-friendly, 60 minutes of music with a short break. Pizza provided!', 'OTHER', '["Pop","Folk / Acoustic"]', 1794547216652, 1.5, 'Austin, TX', 'Grace Community Church — Youth Hall', 35000, NULL, 'BOOKED', 1792732816653, 1792732816907);
INSERT OR IGNORE INTO "Gig" (`id`, `organizerId`, `title`, `description`, `gigType`, `genres`, `eventDate`, `durationHours`, `location`, `venueName`, `budgetCents`, `requirements`, `status`, `createdAt`, `updatedAt`) VALUES ('cmvkitycc000icsmo5s6pc71s', 'cmvkity8y0003csmonk4n00si', 'Wedding ceremony & cocktail hour — string duo', 'Elegant string duo for a garden wedding: 30 min prelude, processional/recessional, and 60 min of cocktail-hour repertoire. Repertoire list shared in advance; bride has requested a specific processional arrangement.', 'WEDDING', '["Classical","Pop"]', 1795670416667, 2.5, 'Fort Worth, TX', 'The Botanical Garden House', 120000, 'Formal attire. Load-in at 3pm sharp; indoor backup in case of rain.', 'OPEN', 1792732816668, 1792732816668);
INSERT OR IGNORE INTO "Gig" (`id`, `organizerId`, `title`, `description`, `gigType`, `genres`, `eventDate`, `durationHours`, `location`, `venueName`, `budgetCents`, `requirements`, `status`, `createdAt`, `updatedAt`) VALUES ('cmvkitycq000kcsmo0xin8qwv', 'cmvkity8y0003csmonk4n00si', 'Corporate gala — jazz trio', 'Three-hour jazz trio for a 250-guest charity gala dinner. Background-appropriate volume, two 45-minute sets with a break during the keynote.', 'CORPORATE', '["Jazz"]', 1792214416681, 3.0, 'Dallas, TX', 'The Crescent Hotel Ballroom', 150000, NULL, 'COMPLETED', 1792732816682, 1792732816824);
